#include <iostream>
#include <fstream>
#include <vector>
#include <cstdint>
#include <limits>
#include <stdexcept>

class FileProcessor {
private:
    std::vector<uint8_t> buffer;
    size_t max_file_size;

    bool validate_size(uint64_t file_size) {
        // line 12: 边界检查 - 拒绝超过max_file_size的文件
        if (file_size > max_file_size) {
            std::cerr << "File size exceeds limit: " << max_file_size << std::endl;
            return false;
        }
        // line 16: 边界检查 - 拒绝超过size_t最大值的文件大小
        if (file_size > std::numeric_limits<size_t>::max()) {
            std::cerr << "File size exceeds size_t capacity" << std::endl;
            return false;
        }
        return true;
    }

public:
    explicit FileProcessor(size_t limit) : max_file_size(limit) {}

    bool process_file(const std::string& path) {
        std::ifstream file(path, std::ios::binary);
        if (!file.is_open()) {
            std::cerr << "Failed to open file" << std::endl;
            return false;
        }

        // line 31: 获取文件大小
        file.seekg(0, std::ios::end);
        uint64_t file_size = static_cast<uint64_t>(file.tellg());
        file.seekg(0, std::ios::beg);

        // line 35: 调用边界检查函数
        if (!validate_size(file_size)) {
            return false;
        }

        // line 38: 分配内存 - file_size已通过验证
        buffer.resize(static_cast<size_t>(file_size));

        // line 41: 读取文件内容
        file.read(reinterpret_cast<char*>(buffer.data()), 
                  static_cast<std::streamsize>(file_size));

        if (!file) {
            std::cerr << "File read error" << std::endl;
            buffer.clear();  // line 46: RAII - 释放内存
            return false;
        }

        // line 50: 处理数据（示例：计算校验和）
        uint32_t checksum = 0;
        for (size_t i = 0; i < buffer.size(); ++i) {
            checksum += buffer[i];
        }
        std::cout << "Checksum: " << checksum << std::endl;

        // line 56: RAII - buffer析构时自动释放
        return true;
    }
};

int main() {
    FileProcessor processor(1024 * 1024);  // 限制1MB
    std::string path = "test.bin";

    if (!processor.process_file(path)) {
        return 1;
    }
    return 0;
}

