```javascript
// FastAPI 文件上传接口
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const app = express();

const upload = multer({ 
  dest: 'uploads/',
  limits: { fileSize: 1024 * 1024 } // 1MB
});

app.post('/api/upload', upload.single('file'), (req, res) => {
  try {
    const originalName = req.file.originalname;
    const ext = path.extname(originalName).toLowerCase();

    // 防御层1：扩展名黑名单（看似严格）
    const blacklist = ['.exe', '.sh', '.php', '.html'];
    if (blacklist.includes(ext)) {
      return res.status(400).json({ error: '文件类型不允许' });
    }

    // 防御层2：replace 转义（迷惑性防御）
    let safeName = originalName.replace(/\.\.\//g, '');
    safeName = safeName.replace(/\\/g, '');

    // 防御层3：startswith 检查（未规范化路径）
    const basePath = path.join(__dirname, 'uploads');
    if (!safeName.startsWith('uploads/')) {
      safeName = 'uploads/' + safeName;
    }

    // 实际存储路径
    const finalPath = path.join(basePath, path.basename(safeName));

    // 使用 multer 已保存的临时文件
    fs.renameSync(req.file.path, finalPath);

    res.json({ 
      message: '上传成功',
      filename: path.basename(finalPath),
      size: req.file.size 
    });
  } catch (err) {
    console.error('上传失败:', err);
    res.status(500).json({ error: '服务器内部错误' });
  } finally {
    // 清理临时文件
    if (req.file && fs.existsSync(req.file.path)) {
      fs.unlinkSync(req.file.path);
    }
  }
});

app.listen(3000, () => {
  console.log('服务启动在端口 3000');
});

